/**
 * Shape of `surveillance-money.json`, generated by
 * `scripts/accountability/build_surveillance_money.py build` from public filings.
 */

export type CompanyId = 'axon' | 'flock';

export type Channel = 'pac' | 'corporate' | 'company_committee' | 'executive' | 'lobbyist' | 'employees';

export type Level = 'federal' | 'state' | 'local' | 'association';

export type VotePosition = 'yes' | 'no' | 'nv' | 'present';

export type Totals = {
  axon: number;
  flock: number;
  total: number;
  byChannel: Partial<Record<Channel, number>>;
};

export type Contribution = {
  company: CompanyId;
  channel: Channel;
  source: string;
  amount: number;
  date?: string;
  donor?: string;
  donorRole?: string;
  via?: string;
  url?: string;
  /** Present only on aggregated rank-and-file employee rows. */
  donorCount?: number;
  contributionCount?: number;
  dateFrom?: string;
  dateTo?: string;
};

export type OfficialContact = {
  phone?: string;
  website?: string;
  twitter?: string;
  facebook?: string;
  instagram?: string;
  contactForm?: string;
  address?: string;
  ballotpedia?: string;
};

export type Official = {
  id: string;
  name: string;
  level: Level;
  state?: string;
  office?: string;
  party?: string;
  current?: boolean;
  bioguide?: string;
  fecIds?: string[];
  contact?: OfficialContact;
  totals: Totals;
  contributions: Contribution[];
  votes?: Record<string, VotePosition>;
};

export type Organization = {
  id: string;
  name: string;
  kind?: string;
  level?: Level;
  state?: string;
  note?: string;
  direction?: 'received';
  totals: Totals;
  contributions: Contribution[];
};

export type RollCall = {
  id: string;
  jurisdiction: string;
  chamber: 'house' | 'senate';
  date: string;
  bill: string;
  title: string;
  question: string;
  result?: string;
  topic: string;
  tally: { yes: number; no: number; other: number };
  lobbiedBy: CompanyId[];
  url: string;
};

export type LobbyingYear = {
  company: CompanyId;
  year: number;
  filings: number;
  reportedAmount: number;
  registrants: string[];
  topIssues: string[];
  bills: string[];
  url: string;
};

export type ReportedItem = {
  company: CompanyId;
  jurisdiction: string;
  summary: string;
  source: string;
  url: string;
};

export type CoverageRow = {
  jurisdiction: string;
  level: string;
  source: string;
  url?: string;
  status: 'searched' | 'partial' | 'not_searched' | 'blocked';
  note?: string;
};

export type CompanyProfile = {
  id: CompanyId;
  name: string;
  formerly?: string;
  hq: string;
  products: string;
  pac: { name: string; fecId: string } | null;
};

export type SurveillanceMoneyDataset = {
  generatedAt: string;
  companies: CompanyProfile[];
  votes: RollCall[];
  officials: Official[];
  organizations: Organization[];
  lobbying: LobbyingYear[];
  reported: ReportedItem[];
  coverage: CoverageRow[];
};
